        customer?: ReadCustomerResponseData;
        currentBalance?: number;
    }): Promise<string | void> {
        if (!this.creditService) {
            TopUpOffering.logger.warn('CreditService not available for topUp');
            return;
        }
        let balance = currentBalance;
        if (balance === undefined || balance === null) {
            const { balance: balanceStr } = await this.creditService.findCreditBalance(
                { businessID: this.businessID, customerId: this.customerId },
                false,
            );
            balance = parseFloat(balanceStr);
